-- Owner-reviewed, official-source-checked insert-only batch (2026-11-05).
-- 12 new records; Zed Student is already represented by the existing /deal/zed record and is not duplicated.
-- Preflight returned zero matches for the 12 new IDs/slugs. No UPDATE or DELETE.
-- Applied to production on 2026-11-05 via three bounded, conflict-safe inserts; post-write SELECT verified 12/12.
-- See docs/primary-source-review-2026-11-05.md for sources and corrections.

SELECT id, slug
FROM public.deals
WHERE id IN ('mindshub-free-tier', 'cto-new-free-forever', 'stepfun-stepaudio-3-free', 'cloady-free-tier', 'daytona-200-free-compute', 'prized-30-free-credit', 'raon-1-mini-free-api', 'tensorlake-free-sandbox', 'flyio-sprites-30-trial', 'vercel-sandbox-free-hobby', 'freestyle-free-vms', 'zai-free-flash-models') OR slug IN ('mindshub-free-tier', 'cto-new-free-forever', 'stepfun-stepaudio-3-free', 'cloady-free-tier', 'daytona-200-free-compute', 'prized-30-free-credit', 'raon-1-mini-free-api', 'tensorlake-free-sandbox', 'flyio-sprites-30-trial', 'vercel-sandbox-free-hobby', 'freestyle-free-vms', 'zai-free-flash-models')
ORDER BY id
LIMIT 100;

BEGIN;
