$reviewed_batch$::jsonb) AS candidate(id text, slug text, name_ar text, name_en text, description_ar text, description_en text, category jsonb, benefits jsonb, eligibility jsonb, pricing jsonb, registration jsonb, official_sources jsonb, get_offer jsonb, review jsonb, status text, ends_at timestamptz)
LIMIT 12
ON CONFLICT DO NOTHING;
COMMIT;

-- Post-insert verification should return 12 active, verified rows.
SELECT id, slug, status, review->>'verdict' AS verdict,
       review->>'reviewed_at' AS reviewed_at,
       eligibility->>'card_required' AS card_required,
       eligibility->'countries'->>'status' AS country_status,
       ends_at
FROM public.deals
WHERE id IN ('mindshub-free-tier', 'cto-new-free-forever', 'stepfun-stepaudio-3-free', 'cloady-free-tier', 'daytona-200-free-compute', 'prized-30-free-credit', 'raon-1-mini-free-api', 'tensorlake-free-sandbox', 'flyio-sprites-30-trial', 'vercel-sandbox-free-hobby', 'freestyle-free-vms', 'zai-free-flash-models')
ORDER BY id
LIMIT 50;
